-- Reference data, part 2: potato and corn diseases (codes from ml/classes.yaml).
-- The same caveats as in V7 apply: Kazakh texts and treatments are drafts that
-- need a native speaker and an agrochemist; dosage is "per the product label".

INSERT INTO diseases (code, crop_code, kind, severity, latin_name, names, symptoms, conditions, prevention) VALUES
    ('potato__late_blight', 'potato', 'oomycete', 'high', 'Phytophthora infestans',
     '{"ru": "Фитофтороз", "kk": "Фитофтороз", "en": "Late blight"}',
     '{"ru": ["Тёмно-бурые расплывчатые пятна на листьях, быстро разрастающиеся", "Белый пушистый налёт по краю пятен с нижней стороны листа", "Бурые пятна на стеблях, твёрдая бурая гниль клубней"],
       "kk": ["Жапырақтарда тез үлкейетін күңгірт қоңыр бұлыңғыр дақтар", "Дақтардың шетінде жапырақтың астыңғы жағында ақ мамықты жабын", "Сабақтарда қоңыр дақтар, түйнектердің қатты қоңыр шіруі"],
       "en": ["Dark brown, spreading blotches on leaves that grow quickly", "White fluffy mould at the edge of the spots on the underside", "Brown streaks on stems and firm brown rot of tubers"]}',
     '{"ru": ["Прохладная влажная погода, туманы и росы", "Дожди и густая ботва", "Заражённые клубни и остатки ботвы"],
       "kk": ["Салқын ылғалды ауа райы, тұман мен шық", "Жаңбыр және қалың жер үсті бөлігі", "Залалданған түйнектер мен сабақ қалдықтары"],
       "en": ["Cool, humid weather, fog and dew", "Rain and a dense canopy", "Infected tubers and haulm debris"]}',
     '{"ru": ["Сажать здоровые клубни, перебирать семенной материал", "Севооборот, не сажать после томата", "Окучивание, чтобы споры не попали на клубни", "Скашивать ботву за 1–2 недели до уборки при признаках болезни"],
       "kk": ["Сау түйнектерді отырғызу, тұқымдық материалды іріктеу", "Ауыспалы егіс, қызанақтан кейін егпеу", "Споралар түйнекке түспеуі үшін төбелеу", "Ауру белгілері болса, жинауға 1–2 апта қалғанда сабақтарды шабу"],
       "en": ["Plant healthy tubers and sort seed stock", "Rotate crops, do not follow tomato", "Hill up so spores do not reach tubers", "Cut the haulm 1–2 weeks before harvest if the disease is present"]}'),

    ('potato__early_blight', 'potato', 'fungal', 'medium', 'Alternaria solani',
     '{"ru": "Альтернариоз", "kk": "Альтернариоз", "en": "Early blight"}',
     '{"ru": ["Тёмно-бурые сухие пятна с концентрическими кольцами на нижних листьях", "Пятна ограничены жилками, вокруг жёлтая кайма", "Тёмные вдавленные пятна на клубнях"],
       "kk": ["Төменгі жапырақтарда концентрлі сақиналы қара қоңыр құрғақ дақтар", "Дақтар тамырлармен шектелген, айналасында сары жиек", "Түйнектерде қараңғы ойық дақтар"],
       "en": ["Dark brown dry spots with concentric rings on lower leaves", "Spots limited by veins with a yellow halo", "Dark sunken spots on tubers"]}',
     '{"ru": ["Тёплая погода, чередование дождей и сухих периодов", "Ослабленные растения, нехватка азота и калия", "Остатки больной ботвы"],
       "kk": ["Жылы ауа райы, жаңбыр мен құрғақ кезеңдердің алмасуы", "Әлсіреген өсімдіктер, азот пен калийдің жетіспеуі", "Ауру сабақ қалдықтары"],
       "en": ["Warm weather with alternating rain and dry spells", "Weakened plants, nitrogen and potassium deficiency", "Infected haulm debris"]}',
     '{"ru": ["Севооборот 3–4 года", "Уборка и уничтожение растительных остатков", "Сбалансированное питание", "Использовать здоровые клубни"],
       "kk": ["3–4 жылдық ауыспалы егіс", "Өсімдік қалдықтарын жинап, жою", "Теңгерімді қоректендіру", "Сау түйнектерді пайдалану"],
       "en": ["Rotate crops over 3–4 years", "Clear and destroy plant debris", "Keep nutrition balanced", "Use healthy tubers"]}'),

    ('potato__healthy', 'potato', 'healthy', NULL, NULL,
     '{"ru": "Здоровое растение", "kk": "Сау өсімдік", "en": "Healthy"}',
     '{"ru": ["Признаков болезни не обнаружено"], "kk": ["Аурудың белгісі табылмады"], "en": ["No signs of disease found"]}',
     NULL,
     '{"ru": ["Регулярно осматривать посадки", "Соблюдать севооборот и использовать здоровые клубни"],
       "kk": ["Екпелерді үнемі тексеріп тұру", "Ауыспалы егісті сақтау және сау түйнектерді пайдалану"],
       "en": ["Inspect the field regularly", "Rotate crops and use healthy tubers"]}'),

    ('corn__common_rust', 'corn', 'fungal', 'medium', 'Puccinia sorghi',
     '{"ru": "Ржавчина", "kk": "Тат", "en": "Common rust"}',
     '{"ru": ["Мелкие овальные коричневато-рыжие пустулы на обеих сторонах листа", "Пустулы рассеяны по листовой пластинке и пылят ржавой спорой при прикосновении", "При сильном поражении листья желтеют и засыхают"],
       "kk": ["Жапырақтың екі жағында ұсақ сопақ қоңырқай-қызыл пустулалар", "Пустулалар жапырақ тақтасына шашыраған, тигенде тат тәрізді спора шашады", "Қатты зақымданғанда жапырақтар сарғайып, кеуіп қалады"],
       "en": ["Small oval brown-orange pustules on both sides of the leaf", "Pustules are scattered over the blade and release rusty spores when touched", "Severely infected leaves yellow and dry out"]}',
     '{"ru": ["Умеренные температуры (16–23 °C) и высокая влажность", "Длительная роса и частые дожди", "Восприимчивые гибриды"],
       "kk": ["Қалыпты температура (16–23 °C) және жоғары ылғалдылық", "Ұзақ шық және жиі жаңбыр", "Бейім будандар"],
       "en": ["Moderate temperatures (16–23 °C) and high humidity", "Long dew periods and frequent rain", "Susceptible hybrids"]}',
     '{"ru": ["Выбирать устойчивые гибриды", "Сеять в оптимальные сроки", "Убирать и заделывать растительные остатки", "Следить за посевами с начала лета"],
       "kk": ["Төзімді будандарды таңдау", "Оңтайлы мерзімде себу", "Өсімдік қалдықтарын жинап, топыраққа көму", "Жаз басынан бастап егістерді бақылау"],
       "en": ["Choose resistant hybrids", "Sow within the optimal window", "Remove and bury crop residue", "Scout fields from early summer"]}'),

    ('corn__northern_leaf_blight', 'corn', 'fungal', 'medium', 'Exserohilum turcicum',
     '{"ru": "Гельминтоспориоз", "kk": "Гельминтоспориоз", "en": "Northern leaf blight"}',
     '{"ru": ["Длинные (5–15 см) сигарообразные серо-зелёные или бурые пятна на листьях", "Пятна со временем темнеют от спороношения", "Сильное поражение сжигает листья, снижается урожай"],
       "kk": ["Жапырақтарда ұзын (5–15 см) шылым тәрізді сұр-жасыл немесе қоңыр дақтар", "Спора түзілуінен дақтар уақыт өте қараяды", "Қатты зақымдану жапырақтарды құрғатады, өнім азаяды"],
       "en": ["Long (5–15 cm) cigar-shaped grey-green or tan lesions on leaves", "Lesions darken with spore production", "Severe infection scorches leaves and reduces yield"]}',
     '{"ru": ["Умеренная температура и частые росы или дожди", "Остатки заражённой соломы на поле", "Монокультура кукурузы"],
       "kk": ["Қалыпты температура және жиі шық не жаңбыр", "Алқаптағы залалданған сабан қалдықтары", "Жүгерінің монокультурасы"],
       "en": ["Moderate temperature and frequent dew or rain", "Infected residue left on the field", "Continuous corn"]}',
     '{"ru": ["Устойчивые гибриды", "Севооборот с не злаковыми культурами", "Глубокая заделка растительных остатков", "Не загущать посевы"],
       "kk": ["Төзімді будандар", "Дәнді емес дақылдармен ауыспалы егіс", "Өсімдік қалдықтарын терең көму", "Егістерді қалың себпеу"],
       "en": ["Resistant hybrids", "Rotate with non-grass crops", "Bury crop residue deeply", "Avoid dense sowing"]}'),

    ('corn__gray_leaf_spot', 'corn', 'fungal', 'medium', 'Cercospora zeae-maydis',
     '{"ru": "Церкоспороз", "kk": "Церкоспороз", "en": "Gray leaf spot"}',
     '{"ru": ["Узкие прямоугольные серые или бурые пятна, ограниченные жилками", "Пятна параллельны жилкам и сливаются", "Поражение начинается с нижних листьев и поднимается вверх"],
       "kk": ["Тамырлармен шектелген тар тікбұрышты сұр немесе қоңыр дақтар", "Дақтар тамырларға параллель және бір-бірімен қосылады", "Зақымдану төменгі жапырақтардан басталып, жоғары көтеріледі"],
       "en": ["Narrow rectangular grey or tan lesions limited by veins", "Lesions run parallel to veins and merge", "Infection starts on lower leaves and moves upward"]}',
     '{"ru": ["Тёплая и влажная погода, длительные туманы", "Безотвальная обработка и остатки на поверхности", "Повторная посадка кукурузы по кукурузе"],
       "kk": ["Жылы және ылғалды ауа райы, ұзақ тұман", "Топырақты аудармай өңдеу және бетіндегі қалдықтар", "Жүгеріні жүгеріден кейін қайта егу"],
       "en": ["Warm, humid weather with long fog periods", "No-till and residue left on the surface", "Corn planted after corn"]}',
     '{"ru": ["Устойчивые гибриды", "Севооборот минимум 1–2 года", "Заделка растительных остатков", "Раннее выявление и мониторинг"],
       "kk": ["Төзімді будандар", "Кемінде 1–2 жылдық ауыспалы егіс", "Өсімдік қалдықтарын көму", "Ерте анықтау және бақылау"],
       "en": ["Resistant hybrids", "Rotation of at least 1–2 years", "Bury crop residue", "Early detection and scouting"]}'),

    ('corn__healthy', 'corn', 'healthy', NULL, NULL,
     '{"ru": "Здоровое растение", "kk": "Сау өсімдік", "en": "Healthy"}',
     '{"ru": ["Признаков болезни не обнаружено"], "kk": ["Аурудың белгісі табылмады"], "en": ["No signs of disease found"]}',
     NULL,
     '{"ru": ["Регулярно осматривать посевы", "Соблюдать севооборот и выбирать устойчивые гибриды"],
       "kk": ["Егістерді үнемі тексеріп тұру", "Ауыспалы егісті сақтау және төзімді будандарды таңдау"],
       "en": ["Scout fields regularly", "Rotate crops and choose resistant hybrids"]}');

INSERT INTO treatments (disease_code, type, product, active_ingredient, dosage, method, sort_order) VALUES
    ('potato__late_blight', 'chemical', 'Mancozeb', 'mancozeb',
     '{"ru": "По инструкции на этикетке препарата", "kk": "Препарат затбелгісіндегі нұсқаулыққа сәйкес", "en": "As directed on the product label"}',
     '{"ru": "Профилактическое опрыскивание до смыкания рядов, повтор через 7–10 дней в сырую погоду", "kk": "Қатарлар жабылғанға дейін профилактикалық бүрку, ылғалды ауа райында 7–10 күннен кейін қайталау", "en": "Preventive spraying before canopy closure, repeat every 7–10 days in wet weather"}', 1),
    ('potato__late_blight', 'chemical', 'Copper oxychloride', 'copper oxychloride',
     '{"ru": "По инструкции на этикетке препарата", "kk": "Препарат затбелгісіндегі нұсқаулыққа сәйкес", "en": "As directed on the product label"}',
     '{"ru": "Опрыскивание ботвы в сухую погоду; соблюдать срок ожидания до уборки", "kk": "Құрғақ ауа райында сабақтарды бүрку; жинауға дейінгі күту мерзімін сақтау", "en": "Spray the haulm in dry weather; observe the pre-harvest interval"}', 2),
    ('potato__late_blight', 'biological', 'Bacillus subtilis-based products', 'Bacillus subtilis',
     '{"ru": "По инструкции на этикетке препарата", "kk": "Препарат затбелгісіндегі нұсқаулыққа сәйкес", "en": "As directed on the product label"}',
     '{"ru": "Профилактические опрыскивания каждые 10–14 дней; против развитой болезни слабее химических", "kk": "10–14 күн сайын профилактикалық бүрку; дамыған ауруға химиялық препараттарға қарағанда әлсіз", "en": "Preventive sprays every 10–14 days; weaker than chemicals against advanced disease"}', 1),

    ('potato__early_blight', 'chemical', 'Mancozeb', 'mancozeb',
